import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { balanceDue } from '../src/payments.js';

test('exportCsv returns header for empty invoices', () => {
  const csv = exportCsv([]);
  assert(csv.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header line', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes one line per invoice', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const csv = exportCsv([issued1.value, issued2.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4);
  assert.equal(lines[3], '');
});

test('exportCsv shows DRAFT for draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const csv = exportCsv([inv.value]);
  const lines = csv.split('\n');
  assert(lines[1].startsWith('DRAFT,'));
});

test('exportCsv includes invoice number for issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert(lines[1].startsWith('INV-2026-0001,'));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('Company A'));
});

test('exportCsv quotes customer names with commas', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('"Company B, Inc."'));
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  const totals = invoiceTotals(issued.value);
  const expectedEuro = (totals.total / 100).toFixed(2);
  assert(csv.includes(expectedEuro));
});

test('exportCsv includes all required columns', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields.length, 10);
});

test('exportCsv includes issueDate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('2026-10-07'));
});

test('exportCsv includes dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('2026-10-15'));
});

test('exportCsv includes status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('issued'));
});

test('exportCsv calculates due correctly for issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedEuro = (totals.total / 100).toFixed(2);
  const lines = csv.split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, expectedEuro);
});

test('exportCsv calculates due correctly for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const due = balanceDue(partial.value);
  const csv = exportCsv([partial.value]);
  const expectedEuro = (due / 100).toFixed(2);
  const lines = csv.split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, expectedEuro);
});

test('exportCsv calculates due as 0 for paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const paid = recordPayment(issued.value, { amount: 19542, date: '2026-10-08' });
  const csv = exportCsv([paid.value]);
  const lines = csv.split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, '0.00');
});

test('exportCsv includes subtotal', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedSubtotal = (totals.subtotal / 100).toFixed(2);
  assert(csv.includes(expectedSubtotal));
});

test('exportCsv includes discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedDiscount = (totals.discount / 100).toFixed(2);
  assert(csv.includes(expectedDiscount));
});

test('exportCsv includes VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const expectedVat = (totals.vat / 100).toFixed(2);
  assert(csv.includes(expectedVat));
});

test('exportCsv ends each line with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.endsWith('\n'));
});

test('exportCsv handles multiple invoices in order', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const csv = exportCsv([issued1.value, issued2.value]);
  const lines = csv.split('\n');
  assert(lines[1].includes('2026-10-05'));
  assert(lines[2].includes('2026-10-10'));
});

test('exportCsv quotes fields with double quotes', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const row = lines[1];
  assert(!row.includes('""'));
});

test('exportCsv formats zero amounts correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const paid = recordPayment(issued.value, { amount: 9771, date: '2026-10-08' });
  const csv = exportCsv([paid.value]);
  assert(csv.includes('0.00'));
});

test('exportCsv handles large amounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []);
  const csv = exportCsv([issued.value]);
  assert(csv.includes('.'));
});

test('exportCsv includes empty dueDate for draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const csv = exportCsv([inv.value]);
  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[3], '');
});

